#!/usr/bin/env bash\n# Test suite for nightly‑uptime‑emoji‑reporter\n\nset -e\n\n# Helper to run a single scenario.\nrun_test() {\n  local mock_load=$1\n  local mock_uptime=$2\n  local expected_emoji=$3\n\n  export MOCK_LOAD="$mock_load"\n  export MOCK_UPTIME="$mock_uptime"\n\n  output=$(bash "$(dirname \"$0\")/../src/uptime_emoji.sh")\n  echo "$output" | grep -q "$expected_emoji" || {\n    echo "Test failed for load=$mock_load (expected $expected_emoji)"\n    exit 1\n  }\n  echo "Passed: load=$mock_load → $expected_emoji"\n}\n\n# Low load → 🌞\nrun_test "0.2" "3d 4h 5m" "🌞"\n\n# Moderate load → 😐\nrun_test "1.0" "1d 2h 3m" "😐"\n\n# High load → 😱\nrun_test "3.5" "0d 0h 30m" "😱"\n\necho "All tests passed."\n
